  private async logoff(callback?: H5MethodParams): Promise<any> {
    if (!USER_INFO.token) {
      callback && callback.complete({
        code: 3003,
        msg: '未登录，请先登录'
      })
      return
    }
    try {
      const res = await getInfoApi()
      if ((res.data?.user_state & 1) === 1) {
        callback && callback.complete({
          code: 0,
          msg: '已提交注销申请'
        })
        this.createModalIframe({
          path: 'logoff?flag=1',
          backgroundColor: '#fff'
        }).then(res => {
          callback && callback.complete(res)
        }).catch(err => {
          callback && callback.complete(err)
        })
        return
      }
      if ((res.data?.user_state & (1 << 1)) !== 0) {
        callback && callback.complete({
          code: 0,
          msg: '已注销'
        })
        return
      }
    } catch (error) {
      console.log(error)
    }

    return this.createModalIframe({
      path: 'logoff',
      backgroundColor: '#fff'
    }).then(res => {
      callback && callback.complete(res)
    }).catch(err => {
      callback && callback.complete(err)
    })
  }

