// @ts-ignore
import Vue from 'vue/dist/vue.esm.browser'
import channelSDK from '@/index.h5_ruixueh5'
// @ts-ignore
// import SdkH5 from './sdk.js'
// import eruda from 'eruda'
// eruda.init()
// eruda.show()

let login_openid = ''
export default function() {
  []
  let sdk: any
  Vue.component('Demo', {
    template: `
      <div>
        <section class='hero is-primary'>
          <div class='hero-body'>
            <div class='container'>
              <h3 class='title'>
                A Demo for 瑞雪h5 SDK
              </h3>
              <h4 class='subtitle'>
                This is a test demo for 瑞雪h5 SDK.
              </h4>
            </div>
          </div>
        </section>

        <section class='hero is-info actions'>
          <div class='hero-body'>
            <div class='container'>
              <button class='button is-primary is-inverted is-outlined' @click='init'>
                初始化
              </button>
              <button class='button is-primary is-inverted is-outlined' @click='loginByOpenid'>
                登录
              </button>
              <button class='button is-primary is-inverted is-outlined' @click='forgetPassword'>
                忘记密码
              </button>
              <button class='button is-primary is-inverted is-outlined' @click='resetPassword'>
                修改密码
              </button>
              <button class='button is-primary is-inverted is-outlined' @click='logoff'>
                注销
              </button>
              <button class='button is-primary is-inverted is-outlined' @click='realName'>
                实名
              </button>
              <button class='button is-primary is-inverted is-outlined' @click='pay'>
                支付
              </button>
              <button class='button is-primary is-inverted is-outlined' @click='openHelpCenter'>
                帮助中心
              </button>
              <button class='button is-primary is-inverted is-outlined' @click='openService'>
                客服中心
              </button>
            </div>
          </div>
        </section>
      </div>
    `,
    data() {
      return {
        sdkLoaded: false
      }
    },
    methods: {
      init() {
        // @ts-ignore
        sdk = new channelSDK({
          productId: '1002',
          channelId: '100',
          cpid: '114',
          baseUrlList: ['https://cn-api-test.ruixueyun.com'],

          // productId: '266',
          // channelId: 'h5test',
          // cpid: '1000336',
          // baseUrlList: ['https://ghmf2.weileyurtr.com'],
          // logSwitch: false,
          complete(res: any) {
            console.log('初始化:', res)
          }
        })

        sdk.setGameInfo('test_role_id', 'test_region_tag')
      },

      login() {
        sdk.login({
          method: 'ruixue'
        }, {
          complete: (res: any) => {
            console.log('登录: ', res)
            if (res.code === 0) {
              localStorage.setItem('login_openid', res.data.login_openid)
            }
          }
        })
      },

      forgetPassword() {
        sdk.forgetPassword({
          complete: (res: any) => {
            console.log('忘记密码: ', res)
          }
        })
      },

      resetPassword() {
        sdk.resetPassword({
          complete: (res: any) => {
            console.log('修改密码: ', res)
          }
        })
      },

      loginByOpenid() {
        let _this = this
        sdk.login({
          method: 'ruixue',
          login_openid: localStorage.getItem('login_openid')
        }, {
          complete: (res: any) => {
            console.log('登录: ', res)
            if (res.code === 0) {
              localStorage.setItem('login_openid', res.data.login_openid)
            } else if (res.code !== 3001) {
              _this.login()
            }
          }
        })
      },

      logoff() {
        sdk.logoff({
          complete: (res: any) => {
            console.log('注销: ', res)
          }
        })
      },

      realName() {
        sdk.realName({
          complete: (res: any) => {
            console.log('实名: ', res)
          }
        })
      },

      openHelpCenter() {
        sdk.openHelpCenter({
          theme: 'light'
        })
      },

      openService() {
        sdk.openService({
          theme: 'light'
        })
      },

      pay() {
        sdk.pay({
          pay_type: 'aums',
          goods_tag: '830001101',
          trade_no: `${new Date().getTime()}`,
          currency: 'CNY'
        }, {
          complete: (res: any) => {
            console.log('支付: ', res)
          }
        })
      }
    }
  })

  new Vue({
    el: '#app'
  })
}
