export const formatTrackParams = ({
                                    eventName,
                                    apiName,
                                    reqParams = {},
                                    errorInfo = {},
                                    loginInfo = {},
                                    ...otherParams
                                  }: any) => {
    const eventNamePrefix = '#rxsdk_'
    return {
      event: eventNamePrefix + eventName,
      properties: {
        api_name: apiName,
        systemInfo: SYSTEM_INFO,
        req_params: { ...reqParams },
        error_info: { ...errorInfo },
        login_info: { ...loginInfo },
        ...otherParams
      }
    }
  }
